#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    int cur_floor = 0;                 /* elevator starts on floor 0 */

    for (int i = 1; i < argc; ++i) {
        long target = strtol(argv[i], NULL, 10);

        /* check validity of the requested floor */
        if (target < 0 || target > 9) {
            puts("INVALID_FLOOR");
            continue;                  /* go on with the next argument */
        }

        /* move the elevator up */
        while (cur_floor < target) {
            printf("MOVE_UP %d->%d\n", cur_floor, cur_floor + 1);
            ++cur_floor;
        }

        /* move the elevator down */
        while (cur_floor > target) {
            printf("MOVE_DOWN %d->%d\n", cur_floor, cur_floor - 1);
            --cur_floor;
        }

        /* we have arrived at the requested floor */
        printf("ARRIVE %d\n", cur_floor);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }

    /* final report */
    printf("FINAL_FLOOR=%d\n", cur_floor);
    return 0;
}
